(function () {
  // Two constants, both measured, both Brotli q11 because that is what the edge
  // serves: the library is a per-first-visit cost, the saving is per submit.
  var LIB = 11735, SAVE = 3968, VISITS = 1000;

  var book = document.getElementById("hb-book");
  var repeat = document.getElementById("hb-repeat");
  if (!book || !repeat) return;

  var bookOut = document.getElementById("hb-book-out");
  var repeatOut = document.getElementById("hb-repeat-out");
  var barCost = document.getElementById("hb-bar-cost");
  var barSave = document.getElementById("hb-bar-save");
  var costNum = document.getElementById("hb-cost");
  var saveNum = document.getElementById("hb-save");
  var verdict = document.getElementById("hb-verdict");
  var cross = document.getElementById("hb-cross");

  // Per 1,000 visits the totals run into megabytes, so the unit follows the
  // number rather than printing four digits of KiB.
  var bytes = function (n) {
    return n >= 1048576 ? (n / 1048576).toFixed(2) + " MiB" : (n / 1024).toFixed(1) + " KiB";
  };

  function paint() {
    var b = Number(book.value) / 100;
    var r = Number(repeat.value) / 100;

    var cost = VISITS * (1 - r) * LIB;
    var saved = VISITS * b * SAVE;
    var net = cost - saved;

    bookOut.textContent = book.value + "%";
    repeatOut.textContent = repeat.value + "%";

    // Both bars share one scale, so their lengths stay comparable.
    var top = Math.max(cost, saved, 1);
    barCost.style.width = (cost / top * 100).toFixed(1) + "%";
    barSave.style.width = (saved / top * 100).toFixed(1) + "%";
    costNum.textContent = bytes(cost);
    saveNum.textContent = bytes(saved);

    if (net > 0) {
      verdict.className = "hb-verdict hb-lose";
      verdict.textContent = "htmx costs " + bytes(net) + " more per 1,000 visits.";
    } else if (net < 0) {
      verdict.className = "hb-verdict hb-win";
      verdict.textContent = "htmx saves " + bytes(-net) + " per 1,000 visits.";
    } else {
      verdict.className = "hb-verdict";
      verdict.textContent = "Exactly break-even.";
    }

    // The booking rate that would pay for the library at this repeat rate. Above
    // 100% it needs more than one submit per visitor, which a booking form cannot
    // produce, so the readout says so rather than printing an unreachable number.
    var needed = (1 - r) * LIB / SAVE;
    cross.textContent = needed > 1
      ? Math.round(needed * 100) + "%, which is more than one submit per visitor"
      : Math.round(needed * 100) + "%";
  }

  book.addEventListener("input", paint);
  repeat.addEventListener("input", paint);

  var reset = document.getElementById("hb-reset");
  if (reset) reset.addEventListener("click", function () {
    book.value = "4";
    repeat.value = "15";
    paint();
  });

  paint();
})();
